  "magic.sug.sales.1": { en: "B2B SaaS sales call script (5 minutes, key questions, and close).", es: "Guión de llamada de ventas B2B SaaS (5 minutos, preguntas clave y cierre)." },
  "magic.sug.sales.2": { en: "Brief commercial proposal for hesitant client (value, price, next steps).", es: "Propuesta comercial breve para cliente indeciso (valor, precio, siguientes pasos)." },
  "magic.sug.sales.3": { en: "Post-demo follow-up email with summary and closing agenda.", es: "Email de seguimiento post-demo con resumen y agenda de cierre." },
  "magic.sug.hr.1": { en: "Job description: Frontend Developer (responsibilities and requirements).", es: "Descripción de puesto: Desarrollador Frontend (responsabilidades y requisitos)." },
